            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and g[yy][xx] == color:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            if len(cells) == 1:
                singleton_cells.add(cells[0])

    fixes = []
    dirs4 = ((-1,0),(1,0),(0,-1),(0,1))
    global_counts = Counter(g[y][x] for y in range(h) for x in range(w)
                            if (y, x) not in singleton_cells)
    boxes = []
    for color, groups in comps.items():
        for cells in groups:
            if len(cells) > 1:
                rs = [p[0] for p in cells]
                cs = [p[1] for p in cells]
                r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
                area = (r1-r0+1) * (c1-c0+1)
                density = len(cells) / area
                if density >= 0.5:
                    boxes.append((color, r0, r1, c0, c1, density, len(cells)))
    for r, c in singleton_cells:
        n4 = [g[y][x] for dy, dx in dirs4
              if 0 <= (y := r + dy) < h and 0 <= (x := c + dx) < w
              and (y, x) not in singleton_cells]
        if not n4:
            continue
        c4 = Counter(n4)
        top4 = max(c4.values())
        winners = {v for v, n in c4.items() if n == top4}
        if len(winners) == 1:
            chosen = next(iter(winners))
        else:
            # Prefer continuation across opposite sides when it resolves a tie.
            opposite = Counter()
            if 0 < r < h-1 and g[r-1][c] == g[r+1][c] and g[r-1][c] in winners:
                opposite[g[r-1][c]] += 1
            if 0 < c < w-1 and g[r][c-1] == g[r][c+1] and g[r][c-1] in winners:
                opposite[g[r][c-1]] += 1
            if opposite and len(opposite) == 1:
                chosen = next(iter(opposite))
            else:
                # Otherwise a matching 2x2 patch identifies a local object fill.
                square_votes = Counter()
                for y0 in (r-1, r):
                    for x0 in (c-1, c):
                        if 0 <= y0 < h-1 and 0 <= x0 < w-1:
                            vals = [g[y][x] for y in range(y0,y0+2)
                                    for x in range(x0,x0+2) if (y,x)!=(r,c)]
                            if len(vals)==3 and len(set(vals))==1 and vals[0] in winners:
                                square_votes[vals[0]] += 1
                if square_votes:
                    chosen = square_votes.most_common(1)[0][0]
                else:
                    # Fill within a dense object's bounding box if one contains it.
                    containing = [b for b in boxes if b[1] <= r <= b[2] and b[3] <= c <= b[4]
                                  and b[0] in winners]
                    if containing:
                        containing.sort(key=lambda b: (b[5], b[6]), reverse=True)
                        chosen = containing[0][0]
                    else:
                        chosen = max(winners, key=lambda v: global_counts[v])
        fixes.append((r, c, chosen))
    for r, c, color in fixes:
        g[r][c] = color
    return g

