def transform(grid):
    g = [row[:] for row in grid]
    h = len(g)
    w = max(map(len, g))
    background = Counter(v for row in g for v in row).most_common(1)[0][0]
    g = [row + [background] * (w - len(row)) for row in g]

    seen = set()
    components = {}
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = g[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen
                            and g[yy][xx] == color):
                        seen.add((yy, xx))
                        q.append((yy, xx))
            components.setdefault(color, []).append(cells)

    # Speck colors occur only in tiny components; larger color regions are intact.
    speck_colors = {color for color, groups in components.items()
                    if groups and all(len(cells) <= 2 for cells in groups)}
    specks = {(r, c) for color in speck_colors
              for cells in components[color] for r, c in cells}

    # Dense components define rectangular colored patches, including cells hidden
    # by speckles. Outside those patches, the underlying color is the background.
    boxes = []
    for color, groups in components.items():
        if color == background or color in speck_colors:
            continue
        for cells in groups:
            if len(cells) < 4:
                continue
            rs = [r for r, _ in cells]
            cs = [c for _, c in cells]
            r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
            area = (r1 - r0 + 1) * (c1 - c0 + 1)
            density = len(cells) / area
            if density >= 0.60:
                boxes.append((area, -density, color, r0, r1, c0, c1))

    out = [row[:] for row in g]
    for r, c in specks:
        # Prefer the smallest dense object patch whose rectangle contains the speck.
        containing = [b for b in boxes if b[3] <= r <= b[4] and b[5] <= c <= b[6]]
        if containing:
            containing.sort()
            out[r][c] = containing[0][2]
        else:
            out[r][c] = background
    return out
